use crate::headers::{Token, TokenKind, collapse_whitespace, decode_word, tokenize};

#[derive(Clone)]
pub struct Mailbox { pub name: String, pub address: String }
pub enum Address { Mailbox(Mailbox), Group(Vec<Mailbox>) }
struct Parser { tokens: Vec<Token>, position: usize, error: bool }
impl Parser {
    fn peek(&self) -> Option<TokenKind> { self.tokens.get(self.position).map(|token| token.kind) }
    fn expect(&mut self, kind: TokenKind) -> Option<()> {
        if self.peek() != Some(kind) { return None; }
        self.position += 1; Some(())
    }
    fn run(&mut self, quoted: bool) -> (usize, usize) {
        let start = self.position;
        while matches!(self.peek(), Some(TokenKind::Word | TokenKind::Special(b'.'))) || quoted && self.peek() == Some(TokenKind::Quoted) { self.position += 1; }
        (start, self.position)
    }
    fn display_name(&mut self, (start, end): (usize, usize)) -> String {
        let (mut result, mut previous) = (String::new(), false);
        for (index, token) in self.tokens[start..end].iter().enumerate() {
            let (text, decoded, failed) = if token.kind == TokenKind::Word { decode_word(&token.text) } else { (token.text.clone(), false, false) };
            self.error |= failed;
            if index > 0 && token.spaced && !(decoded && previous) { result.push(' '); }
            result.push_str(&text); previous = decoded;
        }
        collapse_whitespace(&result)
    }
    fn atom(&self, (start, end): (usize, usize)) -> Option<String> {
        if (end - start) % 2 == 0 { return None; }
        let mut result = String::new();
        for (index, token) in self.tokens[start..end].iter().enumerate() {
            if token.kind != if index % 2 == 0 { TokenKind::Word } else { TokenKind::Special(b'.') } { return None; }
            result.push_str(&token.text);
        }
        Some(result)
    }
    fn address(&mut self, in_group: bool) -> Option<Address> {
        let phrase = self.run(true);
        match self.peek()? {
            TokenKind::Special(b'<') => {
                self.position += 1;
                let local = self.run(false); self.expect(TokenKind::Special(b'@'))?;
                let domain = self.run(false); self.expect(TokenKind::Special(b'>'))?;
                let address = format!("{}@{}", self.atom(local)?, self.atom(domain)?).to_ascii_lowercase();
                let name = self.display_name(phrase);
                Some(Address::Mailbox(Mailbox { name, address }))
            }
            TokenKind::Special(b'@') => {
                self.position += 1;
                let domain = self.run(false);
                let address = format!("{}@{}", self.atom(phrase)?, self.atom(domain)?).to_ascii_lowercase();
                Some(Address::Mailbox(Mailbox { name: String::new(), address }))
            }
            TokenKind::Special(b':') if phrase.0 < phrase.1 && !in_group => {
                self.position += 1;
                let mut mailboxes = Vec::new();
                if self.peek() != Some(TokenKind::Special(b';')) {
                    loop {
                        let Address::Mailbox(mailbox) = self.address(true)? else { return None; };
                        mailboxes.push(mailbox);
                        if self.peek() != Some(TokenKind::Special(b',')) { break; }
                        self.position += 1;
                    }
                }
                self.expect(TokenKind::Special(b';'))?;
                Some(Address::Group(mailboxes))
            }
            _ => None,
        }
    }
}
pub fn parse_address_list(value: &str) -> Option<(Vec<Address>, bool)> {
    let mut parser = Parser { tokens: tokenize(value, true)?, position: 0, error: false };
    let mut addresses = vec![parser.address(false)?];
    while parser.peek() == Some(TokenKind::Special(b',')) { parser.position += 1; addresses.push(parser.address(false)?); }
    (parser.position == parser.tokens.len()).then_some((addresses, parser.error))
}

use crate::headers::{remove_comments, split_words};

const WEEKDAYS: [&str; 7] = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];
const MONTHS: [&str; 12] = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
fn leap(year: i64) -> bool { year % 4 == 0 && year % 100 != 0 || year % 400 == 0 }
fn month_days(year: i64, month: usize) -> i64 { if month == 2 && leap(year) { 29 } else { [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1] } }
fn year_days(year: i64) -> i64 { if leap(year) { 366 } else { 365 } }
fn digits(text: &str, lengths: &[usize]) -> bool { lengths.contains(&text.len()) && text.bytes().all(|byte| byte.is_ascii_digit()) }
pub fn parse_date(value: &str) -> Result<i64, &'static str> {
    let syntax = "bad Date syntax";
    let range = "Date out of range";
    let text = remove_comments(value).ok_or(syntax)?.replace(',', " , ");
    let mut tokens = split_words(&text);
    let mut weekday = None;
    if tokens.len() >= 3 && tokens[1] == "," {
        if let Some(day) = WEEKDAYS.iter().position(|word| tokens[0].eq_ignore_ascii_case(word)) { weekday = Some(day); tokens.drain(..2); }
    }
    if tokens.len() != 5 { return Err(syntax); }
    let (day_text, month_text, year_text, time, zone) = (tokens[0], tokens[1], tokens[2], tokens[3], tokens[4]);
    let month = MONTHS.iter().position(|word| month_text.eq_ignore_ascii_case(word)).ok_or(syntax)? + 1;
    let pieces: Vec<_> = time.split(':').collect();
    let numeric = zone.starts_with(['+', '-']) && digits(&zone[1..], &[4]);
    let named = match zone.to_ascii_lowercase().as_str() { "ut" | "gmt" | "z" => Some(0), "est" | "cdt" => Some(-300),
        "edt" => Some(-240), "cst" | "mdt" => Some(-360), "mst" | "pdt" => Some(-420), "pst" => Some(-480), _ => None };
    if !digits(day_text, &[1, 2]) || !digits(year_text, &[2, 4]) || ![2, 3].contains(&pieces.len()) || pieces.iter().any(|part| !digits(part, &[2])) || !(numeric || named.is_some()) { return Err(syntax); }
    let day: i64 = day_text.parse().unwrap();
    let mut year: i64 = year_text.parse().unwrap();
    if year_text.len() == 2 { year += if year < 50 { 2000 } else { 1900 }; }
    let hour: i64 = pieces[0].parse().unwrap();
    let minute: i64 = pieces[1].parse().unwrap();
    let second: i64 = if pieces.len() == 3 { pieces[2].parse().unwrap() } else { 0 };
    let offset = if numeric {
        let hours: i64 = zone[1..3].parse().unwrap();
        let minutes: i64 = zone[3..5].parse().unwrap();
        if hours > 23 || minutes > 59 { return Err(range); }
        (hours * 60 + minutes) * if zone.starts_with('-') { -1 } else { 1 }
    } else { named.unwrap() };
    if !(1970..=2099).contains(&year) || day < 1 || day > month_days(year, month) || hour > 23 || minute > 59 || second > 59 { return Err(range); }
    let days: i64 = (1970..year).map(year_days).sum::<i64>() + (1..month).map(|month| month_days(year, month)).sum::<i64>() + day - 1;
    let seconds = days * 86400 + hour * 3600 + minute * 60 + second - offset * 60;
    if seconds < 0 { return Err(range); }
    if weekday.is_some_and(|weekday| ((days + 3) % 7) as usize != weekday) { return Err("Date weekday mismatch"); }
    Ok(seconds)
}
pub fn format_utc(seconds: i64) -> String {
    let (mut days, rest) = (seconds / 86400, seconds % 86400);
    let (mut year, mut month) = (1970, 1);
    while days >= year_days(year) { days -= year_days(year); year += 1; }
    while days >= month_days(year, month) { days -= month_days(year, month); month += 1; }
    format!("{year:04}-{month:02}-{:02} {:02}:{:02}:{:02}", days + 1, rest / 3600, rest % 3600 / 60, rest % 60)
}

use std::collections::BTreeMap;
use crate::mime::{hex_byte, strict_base64};

pub struct Header { pub fields: Vec<(String, String)>, pub invalid_lines: Vec<usize> }
impl Header {
    pub fn value(&self, name: &str) -> Option<&str> { self.fields.iter().find(|(key, _)| key.eq_ignore_ascii_case(name)).map(|(_, value)| value.as_str()) }
    pub fn count(&self, name: &str) -> usize { self.fields.iter().filter(|(key, _)| key.eq_ignore_ascii_case(name)).count() }
}
#[derive(Clone, Copy, PartialEq)]
pub enum TokenKind { Word, Quoted, Special(u8) }
pub struct Token { pub kind: TokenKind, pub text: String, pub spaced: bool }
pub fn split_words(text: &str) -> Vec<&str> { text.split([' ', '\t']).filter(|word| !word.is_empty()).collect() }
pub fn collapse_whitespace(text: &str) -> String { split_words(text).join(" ") }
pub fn parse_fields(lines: &[(usize, String)]) -> Header {
    let mut header = Header { fields: Vec::new(), invalid_lines: Vec::new() };
    let mut in_field = false;
    for (number, text) in lines {
        if text.starts_with([' ', '\t']) {
            if in_field { header.fields.last_mut().unwrap().1.push_str(text); }
            else { header.invalid_lines.push(*number); }
            continue;
        }
        in_field = false;
        if let Some((name, value)) = text.split_once(':') {
            if !name.is_empty() && name.bytes().all(|byte| (33..=126).contains(&byte)) {
                header.fields.push((name.to_ascii_lowercase(), value.to_owned())); in_field = true;
            }
        }
        if !in_field { header.invalid_lines.push(*number); }
    }
    for (_, value) in &mut header.fields { *value = value.trim_matches([' ', '\t']).to_owned(); }
    header
}
pub fn remove_comments(text: &str) -> Option<String> {
    let mut result = String::new();
    let (mut depth, mut escaped) = (0usize, false);
    for byte in text.bytes() {
        if depth == 0 {
            if byte == b'(' { depth = 1; result.push(' '); } else { result.push(byte as char); }
        } else if escaped { escaped = false; }
        else if byte == b'\\' { escaped = true; }
        else if byte == b'(' { depth += 1; }
        else if byte == b')' { depth -= 1; }
    }
    (depth == 0).then_some(result)
}
fn word_byte(byte: u8, address: bool) -> bool {
    if address { byte.is_ascii_alphanumeric() || b"!#$%&'*+-/=?^_`{|}~".contains(&byte) }
    else { (33..=126).contains(&byte) && !b"()<>@,;:\\\"/[]?=".contains(&byte) }
}
pub fn tokenize(text: &str, address: bool) -> Option<Vec<Token>> {
    let data = text.as_bytes();
    let specials: &[u8] = if address { b"<>:;@,." } else { b"/;=" };
    let (mut position, mut spaced) = (0, false);
    let mut tokens = Vec::new();
    while position < data.len() {
        let byte = data[position];
        if byte == b' ' || byte == b'\t' { spaced = true; position += 1; continue; }
        if byte == b'(' {
            let mut depth = 1;
            position += 1;
            while position < data.len() && depth > 0 {
                match data[position] { b'\\' => { position += 2; continue; }, b'(' => depth += 1, b')' => depth -= 1, _ => {} }
                position += 1;
            }
            if depth != 0 { return None; }
            spaced = true; continue;
        }
        if byte == b'"' {
            position += 1;
            let mut value = String::new();
            while position < data.len() && data[position] != b'"' {
                if data[position] == b'\\' { position += 1; }
                value.push(*data.get(position)? as char); position += 1;
            }
            if position == data.len() { return None; }
            position += 1;
            tokens.push(Token { kind: TokenKind::Quoted, text: value, spaced });
        } else if specials.contains(&byte) {
            tokens.push(Token { kind: TokenKind::Special(byte), text: (byte as char).to_string(), spaced }); position += 1;
        } else if word_byte(byte, address) {
            let start = position;
            while position < data.len() && word_byte(data[position], address) { position += 1; }
            tokens.push(Token { kind: TokenKind::Word, text: text[start..position].to_owned(), spaced });
        } else { return None; }
        spaced = false;
    }
    Some(tokens)
}
pub fn decode_word(word: &str) -> (String, bool, bool) {
    if word.len() < 4 || !word.starts_with("=?") || !word.ends_with("?=") { return (word.to_owned(), false, false); }
    let pieces: Vec<_> = word[2..word.len() - 2].split('?').collect();
    if pieces.len() != 3 || pieces.iter().any(|part| part.is_empty()) { return (word.to_owned(), false, false); }
    let decode = || -> Option<String> {
        if !pieces[0].eq_ignore_ascii_case("us-ascii") { return None; }
        let data = match pieces[1] {
            "B" | "b" => strict_base64(pieces[2])?,
            "Q" | "q" => {
                let bytes = pieces[2].as_bytes();
                let mut result = Vec::new();
                let mut position = 0;
                while position < bytes.len() {
                    match bytes[position] { b'_' => { result.push(32); position += 1; },
                        b'=' => { result.push(hex_byte(bytes, position + 1)?); position += 3; },
                        byte => { result.push(byte); position += 1; } }
                }
                result
            }
            _ => return None,
        };
        if data.iter().all(|byte| (32..=126).contains(byte)) { Some(String::from_utf8(data).unwrap()) } else { None }
    };
    match decode() { Some(text) => (text, true, false), None => (word.to_owned(), false, true) }
}
pub fn decode_unstructured(value: &str) -> (String, bool) {
    let (mut result, mut previous, mut error) = (String::new(), false, false);
    for (index, word) in split_words(value).into_iter().enumerate() {
        let (text, decoded, failed) = decode_word(word);
        if index > 0 && !(decoded && previous) { result.push(' '); }
        result.push_str(&text); previous = decoded; error |= failed;
    }
    (collapse_whitespace(&result), error)
}
pub struct Parameters { pub main_type: String, pub subtype: String, pub values: BTreeMap<String, String> }
pub fn parse_parameters(value: &str, with_subtype: bool) -> Option<Parameters> {
    let tokens = tokenize(value, false)?;
    if tokens.first()?.kind != TokenKind::Word { return None; }
    let mut result = Parameters { main_type: tokens[0].text.to_ascii_lowercase(), subtype: String::new(), values: BTreeMap::new() };
    let mut position = 1;
    if with_subtype {
        if tokens.get(1)?.kind != TokenKind::Special(b'/') || tokens.get(2)?.kind != TokenKind::Word { return None; }
        result.subtype = tokens[2].text.to_ascii_lowercase(); position = 3;
    }
    while position < tokens.len() {
        if position + 4 > tokens.len() || tokens[position].kind != TokenKind::Special(b';') || tokens[position + 1].kind != TokenKind::Word ||
            tokens[position + 2].kind != TokenKind::Special(b'=') || !matches!(tokens[position + 3].kind, TokenKind::Word | TokenKind::Quoted) { return None; }
        result.values.entry(tokens[position + 1].text.to_ascii_lowercase()).or_insert_with(|| tokens[position + 3].text.clone());
        position += 4;
    }
    Some(result)
}

mod headers;
